"""FM-16S original pathways: transformed roots and angular reasoning."""
import sympy as s
from calibration_bank import LEVELS,L
x,h,m=s.symbols('x h m',real=True); R=s.Rational; pi=s.pi
PATHS={'scaled-roots':'ALG.related-quadratic.scale','shifted-roots':'ALG.related-quadratic.shift','argument-normalization':'CPX.polar-arithmetic.normalize','exact-radians':'CPX.radians.exact'}
RATIONALES={
'scaled-roots':['Expand scalar products.','Diagnose the product scaling exponent.','Construct a scaled-root quadratic.','Compose two scalings and compare coefficients.','Recover a signed scale from target coefficients.','Classify every scale from a prescribed discriminant, including zero.'],
'shifted-roots':['Translate an individual root.','Diagnose a substitution-direction error.','Construct a shifted-root equation.','Recover a shift from the sum and verify invariance of root separation.','Find shifts giving a prescribed root product and sign.','Classify all shifts giving real roots of opposite signs and a variable product.'],
'argument-normalization':['Convert integral turns to radians.','Diagnose the excluded principal endpoint.','Normalize a single exact angle.','Normalize a product and quotient of complex numbers.','Recover all angles under a multiplication constraint in a bounded range.','Classify a parameter-dependent quotient argument with all wrap boundaries.'],
'exact-radians':['Recall exact sine and cosine.','Diagnose quadrant signs.','Evaluate exact trig expressions.','Recover an exact Cartesian product via angle addition.','Solve a trigonometric constraint with quadrant restrictions.','Enrichment: classify all angles with a prescribed linear combination of sine and cosine, using a supplied identity.']}
def make(path,l,v):
 if path not in PATHS or l not in LEVELS or v not in (1,2,3):raise ValueError('Unknown cell')
 a=v+1;b=2*v+4;d=2*v+5;S=a+b;P=a*b;F=(x-a)*(x-b)
 if path=='scaled-roots':
  if l==1:
   f=[a*d,b*d];q=f'Two numbers are {a} and {b}. Multiply both by {d} and state the two results.';ans=f'{f[0]}, {f[1]}';steps=[f'Multiply each number separately: {a} times {d}={f[0]} and {b} times {d}={f[1]}.'];hint=['Scale both numbers.','Do not add the scale.'];mist='Adding rather than multiplying.'
  elif l==2:
   f=[d*S,d*d*P];q=f'A student says scaling both roots of {L(s.expand(F))}=0 by {d} multiplies both their sum and product by {d}. Correct both quantities and explain.';ans=f'Sum {f[0]}, product {f[1]}.';steps=[f'Original sum is {S} and product is {P}.',f'The sum scales once, to {f[0]}; the product contains two scaled factors, giving {f[1]}.'];hint=['Write the new roots as d times each original root.','Multiply the two scaled factors.'];mist='Using d rather than d squared in the product.'
  elif l==3:
   G=x*x+d*S*x+d*d*P;f=[G];q=f'Construct the monic equation with roots {-d} times the roots of {L(s.expand(F))}=0, without solving the original equation.';ans=L(G)+'=0';steps=[f'Original sum {S}, product {P}.',f'New sum {-d*S}, product {d*d*P}.',f'Insert these into the monic equation: {L(G)}=0.'];hint=['Scale the sum by the signed factor.','Square the scale for the product.'];mist='Negating the product when both roots are negated.'
  elif l==4:
   m=-a*b;G=x*x-m*S*x+m*m*P;f=[m,G];q=f'The roots of {L(s.expand(F))}=0 are first scaled by {a}, then by {-b}. Construct the resulting monic equation. Explain why reversing the two scalings leaves the result unchanged.';ans=f'Net scale {m}; {L(G)}=0.';steps=[f'The net factor is {a} times {-b}={m}.',f'The new sum is {m*S}, product {m*m*P}.',f'The equation is {L(G)}=0.', 'Real scalar multiplication commutes, so reversing the order has no effect.'];hint=['Combine the two scale factors.','Apply the sum and product rules.'];mist='Adding the two scale factors.'
  elif l==5:
   m=-d;G=x*x-m*S*x+m*m*P;f=[m,G];q=f'A monic equation is obtained by scaling both roots of {L(s.expand(F))}=0 by a real m. Its constant is {d*d*P} and its linear coefficient is positive. Determine m and the full equation; prove uniqueness.';ans=f'm={m}; {L(G)}=0.';steps=[f'The constant is m^2 times {P}, so m=+/-{d}.',f'The linear coefficient is -{S}m; positivity forces m={m}.',f'The equation is {L(G)}=0. Both conditions hold and the other sign fails.'];hint=['The constant determines the magnitude of m.','Use the sign of the linear coefficient.'];mist='Retaining both signs despite the condition.'
  else:
   m=s.Symbol('m',real=True);D=(b-a)**2;G=x*x-m*S*x+m*m*P;f=[D,s.sqrt(h/D),G];q=f'For every real h consider the monic quadratic obtained by scaling both roots of {L(s.expand(F))}=0 by an unknown real m. Its discriminant is h. Find every resulting equation, classifying the number of distinct equations and the signs of their roots. Include h=0.';ans=f'h<0: none; h=0: x^2=0; h>0: m=+/-sqrt(h/{D}), equations x^2-{S}m x+{P}m^2=0.';steps=[f'The transformed sum is {S}m and product {P}m^2.',f'The discriminant is ({S}m)^2-4({P}m^2)={D}m^2.',f'For negative h no real scale exists. At h=0 only m=0 works, giving the repeated zero root.',f'For h>0 the two scales are +/-sqrt(h/{D}). The equations are distinct since their linear coefficients have opposite nonzero signs.', 'The original roots are both positive, so positive scaling gives two positive roots and negative scaling gives two negative roots. These choices exhaust the real scales.'];hint=['Express the discriminant in terms of m.','Treat the zero scale separately.'];mist='Assuming scaling must be nonzero even though the prompt permits zero.'
 elif path=='shifted-roots':
  if l==1:
   f=[a-d,b-d];q=f'Subtract {d} from each of the two numbers {a} and {b}. Give the results.';ans=str(f);steps=[f'Translate each number by {-d}: {f[0]}, {f[1]}.'];hint=['Subtract from each separately.','Keep negative results.'];mist='Subtracting the number from the shift.'
  elif l==2:
   G=s.expand(F.subs(x,x-d));f=[G];q=f'A student uses f(x+{d}) to obtain roots shifted up by {d}, where f(x)={L(s.expand(F))}. Explain the error and give the corrected polynomial.';ans=L(G);steps=[f'If r is an original root, f(r)=0. For the new root r+{d}, the input must be r.',f'Use f(x-{d}) instead, which expands to {L(G)}.'];hint=['Test the claimed new root in the substituted function.','The sign inside the function is opposite the root shift.'];mist='Using the same sign in the substitution as in the root shift.'
  elif l==3:
   G=s.expand(F.subs(x,x+d));f=[G];q=f'Without finding the original roots, construct the monic quadratic with roots alpha-{d}, beta-{d}, where alpha,beta solve {L(s.expand(F))}=0.';ans=L(G)+'=0';steps=[f'New sum {S-2*d}; new product {P-d*S+d*d}.',f'Use the monic coefficient identities to get {L(G)}=0.'];hint=['Both roots change by the same amount.','Expand the product of shifted roots.'];mist='Omitting the squared shift in the product.'
  elif l==4:
   m=d;G=s.expand(F.subs(x,x-m));f=[m,G,(b-a)**2];q=f'Both roots of {L(s.expand(F))}=0 are shifted by m. The new root sum is {S+2*m}. Determine m and the equation, then verify the discriminant is unchanged.';ans=f'm={m}; {L(G)}=0; discriminant {(b-a)**2}.';steps=[f'New sum is {S}+2m, so m={m}.',f'Substitute x-{m} into the original polynomial: {L(G)}.',f'The discriminant is {(b-a)**2}, unchanged because the difference of the two roots is unchanged.'];hint=['The sum changes by twice the shift.','Compare squared root differences.'];mist='Assuming the discriminant changes with the constant alone.'
  elif l==5:
   m=d;C=(a+m)*(b+m);G=s.expand(F.subs(x,x-m));f=[m,G];q=f'Both roots of {L(s.expand(F))}=0 are shifted by a real m. Their product becomes {C} and both shifted roots are positive. Find m and the resulting equation, proving uniqueness.';ans=f'm={m}; {L(G)}=0.';steps=[f'The product condition is m^2+{S}m+{P}={C}.',f'The two solutions are {m} and {-S-m}, since their sum is -{S}.',f'The second shift makes both roots negative; positivity selects {m}.',f'The resulting equation is {L(G)}=0, which satisfies both conditions.'];hint=['Expand the shifted product.','Check the signs for each candidate shift.'];mist='Accepting the other shift without checking positivity.'
  else:
   D=(b-a)**2;bound=-R(D,4);m1=(-S-s.sqrt(D+4*h))/2;m2=(-S+s.sqrt(D+4*h))/2;f=[bound,m1,m2];q=f'The roots of {L(s.expand(F))}=0 are both shifted by a real m. For every real h determine all shifts making their product h and making the shifted roots strictly opposite in sign. Classify the number of valid shifts, including every boundary.';ans=f'h<{L(bound)} or h>=0: none; h={L(bound)}: m={L(-R(S,2))}; {L(bound)}<h<0: m={L(m1)} or {L(m2)}.';steps=[f'The product is (m+{a})(m+{b})=m^2+{S}m+{P}.',f'Its minimum by completing the square is {L(bound)}, attained at m={L(-R(S,2))}.',f'Opposite signs require h<0, excluding both zero-product cases and all positive products.',f'For {L(bound)}<h<0 the quadratic in m gives two distinct real shifts {L(m1)}, {L(m2)}. At the minimum they coincide.', 'Each admissible shift gives real roots with negative product, hence strictly opposite signs; the other parameter ranges cannot work.'];hint=['Complete the square in the shift variable.','Use the strict sign condition on the product.'];mist='Allowing a zero root as an opposite-sign pair.'
 elif path=='argument-normalization':
  norm=lambda t:s.simplify(t-2*pi*s.ceiling((t-pi)/(2*pi)))
  if l==1:
   f=[2*a*pi];q=f'Express {a} complete anticlockwise turns in exact radians.';ans=L(f[0]);steps=['One complete turn is 2 pi radians.',f'Multiply by {a}: {L(f[0])}.'];hint=['One turn is a full circle.','Multiply 2 pi by the count.'];mist='Using pi for a full turn.'
  elif l==2:
   T=-(2*a+1)*pi;f=[pi];q=f'A student gives {L(T)} as the principal argument of a negative real number. Correct it in (-pi,pi] and explain why -pi is not accepted.';ans=L(pi);steps=[f'Add {a+1} complete turns to {L(T)} to obtain pi.','The negative real axis has principal argument pi; the interval excludes -pi.'];hint=['Angles differing by a full turn represent the same ray.','Check which endpoint is included.'];mist='Using the excluded endpoint -pi.'
  elif l==3:
   T=R(2*d+1,4)*pi;f=[norm(T)];q=f'Normalize the angle {L(T)} to the principal range (-pi,pi].';ans=L(f[0]);steps=[f'Subtract an integer multiple of 2 pi from {L(T)}.',f'The equivalent angle {L(f[0])} is in the required interval.'];hint=['Subtract full turns, not half turns.','Check both interval endpoints.'];mist='Stopping after one turn when another is needed.'
  elif l==4:
   A=R(3,4)*pi;B=R(2*v+3,8)*pi;C=-R(3,4)*pi;f=[norm(A+B),norm(A+B-C)];q=f'Nonzero z,w,u have arguments {L(A)}, {L(B)}, {L(C)}. Determine the principal arguments of zw and zw/u, showing each normalization.';ans=', '.join(L(e) for e in f);steps=[f'For zw add arguments to get {L(A+B)}, normalizing to {L(f[0])}.',f'For zw/u subtract the argument of u from the unwrapped sum, giving {L(A+B-C)}.',f'Normalize this to {L(f[1])}; both results lie in (-pi,pi].'];hint=['Add for a product; subtract for a quotient.','Reduce modulo 2 pi after combining.'];mist='Adding the divisor argument.'
  elif l==5:
   T=R(v,4)*pi;f=[(T-2*pi)/2,T/2,(T+2*pi)/2];f=[e for e in f if -pi<e<=pi];q=f'A nonzero z has principal argument theta in (-pi,pi]. The principal argument of z squared is {L(T)}. Determine every possible theta and prove completeness.';ans=', '.join(L(e) for e in f);steps=[f'The unwrapped doubled angle must equal {L(T)} plus an integer multiple of 2 pi.',f'Dividing by two gives theta={L(T/2)}+n pi.',f'Restricting to (-pi,pi] leaves {ans}.', 'All other integers put theta outside the required interval; both candidates yield the prescribed argument.'];hint=['Do not just halve the principal angle.','Include all full-turn equivalents before dividing.'];mist='Missing the second possible argument.'
  else:
   A=R(v,4)*pi;lo=-pi+A;hi=pi+A;f=[lo,hi];q=f'Nonzero z and w have arguments congruent to t and {L(A)} respectively, with real t in [-2pi,2pi]. Classify the principal argument of z/w as a piecewise function of t. Give exact wrap boundaries and justify the choice at each boundary.';ans=f't<={L(lo)}: t-{L(A)}+2pi; {L(lo)}<t<={L(hi)}: t-{L(A)}; t>{L(hi)}: t-{L(A)}-2pi (within the stated domain).';steps=[f'The raw quotient angle is t-{L(A)}.',f'This equals -pi at t={L(lo)} and +pi at t={L(hi)}.',f'For -2pi<=t<={L(lo)}, add 2pi to reach (-pi,pi]; equality at the lower boundary gives pi.',f'For {L(lo)}<t<={L(hi)}, the raw angle is already in range, including the upper endpoint.',f'For {L(hi)}<t<=2pi, subtract 2pi. The three disjoint intervals cover the domain and each output is congruent to the raw quotient angle.'];hint=['Locate where the raw angle reaches the principal endpoints.','Remember -pi is excluded but pi is included.'];mist='Putting the lower wrap boundary into the middle interval.'
 else:
  T=[pi/6,pi/4,pi/3][v-1];C=s.cos(T);N=s.sin(T)
  if l==1:
   f=[C,N];q=f'Find the exact cosine and sine of {L(T)} radians.';ans=', '.join(L(e) for e in f);steps=[f'Use the special-angle triangle to obtain cosine {L(C)} and sine {L(N)}.'];hint=['Use a 30-60-90 or 45-45-90 triangle.','Keep radicals exact.'];mist='Interchanging sine and cosine.'
  elif l==2:
   f=[-C,N];q=f'A student gives both sine and cosine of {L(pi-T)} as positive. Correct the exact values using the quadrant.';ans=f'Cosine {L(-C)}, sine {L(N)}.';steps=['The angle is in quadrant II, where cosine is negative and sine positive.',f'The reference angle is {L(T)}, so cosine {L(-C)} and sine {L(N)}.'];hint=['Locate the angle on the unit circle.','Use the reference angle.'];mist='Ignoring quadrant signs.'
  elif l==3:
   E=s.simplify(a*C-b*N);f=[E];q=f'Evaluate {a} cos({L(T)}) - {b} sin({L(T)}) exactly.';ans=L(E);steps=[f'Substitute cos={L(C)}, sin={L(N)}.',f'Simplify the resulting radical expression to {L(E)}.'];hint=['Use exact special-angle values.','Collect like radicals only.'];mist='Rounding the trig values before simplifying.'
  elif l==4:
   U=pi/2-T;A=a*(C+s.I*N);B=b*(s.cos(U)+s.I*s.sin(U));f=[s.expand(A*B)];q=f'Use exact trig values and angle addition to multiply {L(A)} by {L(B)}. Give the Cartesian answer and explain why the real part vanishes.';ans=L(f[0]);steps=[f'The numbers have positive moduli {a},{b} and arguments {L(T)}, {L(U)}.',f'The product has modulus {a*b} and argument pi/2.',f'At pi/2 cosine is zero and sine is one, so the Cartesian result is {L(f[0])}.'];hint=['Identify the special-angle forms.','The arguments are complementary.'];mist='Multiplying arguments rather than adding them.'
  elif l==5:
   f=[pi-T];q=f'Find every theta in [0,2pi) satisfying sin(theta)={L(N)} and cos(theta)<0, giving the exact radian answer and proving uniqueness.';ans=L(f[0]);steps=[f'The positive sine has reference angle {L(T)}.', 'Sine is positive in quadrants I and II; negative cosine selects II.',f'Thus theta={L(pi-T)}. The strict cosine condition excludes the quadrant I solution and no other quadrant has positive sine.'];hint=['Find the reference angle.','Use the cosine inequality.'];mist='Keeping both positive-sine solutions.'
  else:
   # Use a phase shift, with exact coefficient pair, no general inverse trig assumptions beyond supplied identity.
   phi=T;M=a;A=s.simplify(M*s.cos(phi));B=s.simplify(M*s.sin(phi));f=[M,phi,-M,M,phi-s.acos(h/M),phi+s.acos(h/M)];q=f'For every real h classify and find all theta in [0,2pi) satisfying {L(A)} cos(theta)+{L(B)} sin(theta)=h. You may use cos(theta-phi)=cos(theta)cos(phi)+sin(theta)sin(phi). Give exact expressions using inverse cosine where needed and handle repeated or wrapped solutions.';ans=f'|h|>{M}: none; h={M}: theta={L(phi)}; h={-M}: theta={L(phi+pi)}; otherwise theta={L(phi)} +/- arccos(h/{M}), each reduced modulo 2pi into [0,2pi).';steps=[f'Factor {M} and apply the supplied identity: the left side equals {M} cos(theta-{L(phi)}).',f'Cosine ranges from -1 to 1, so |h|>{M} is impossible.',f'At h={M} and h={-M}, the unique angles modulo 2pi are {L(phi)} and {L(phi+pi)} respectively.',f'For -{M}<h<{M}, put gamma=arccos(h/{M}) in (0,pi). Then theta={L(phi)}+gamma or {L(phi)}-gamma modulo 2pi.', 'Choose the unique representative in [0,2pi) for each. They cannot coincide modulo 2pi because 0<2gamma<2pi. The cosine solutions exhaust a full turn.'];hint=['Recognize the exact phase shift.','Find both cosine branches and reduce to the specified interval.'];mist='Taking only the principal inverse cosine solution.'
 return dict(path=path,focus_skill=PATHS[path],tier=l,variant=v,assessment_role='prerequisite_bridge' if l==1 else 'concept_diagnostic' if l==2 else 'direct_focus_task',question_latex=q,final_answer_latex=ans,worked_solution_latex=steps,progressive_hints=hint,rubric=[dict(marks=1,criterion=e) for e in steps],facts=[str(e) for e in f],likely_mistake=mist,origin='original',examination_source=None,difficulty_status='editorial_design_teacher_pending',demand_rationale=RATIONALES[path][l-1])
